/**
 * marked.min.js - Lightweight, standalone Markdown parser
 *
 * This provides standard Markdown parsing directly in the browser with
 * zero external dependencies, supporting headings, lists, checkboxes,
 * code blocks, blockquotes, tables, links, and text formatting.
 */
(function (global) {
  'use strict';

  function escapeHtml(str) {
    return str
      .replace(/&/g, '&amp;')
      .replace(/</g, '&lt;')
      .replace(/>/g, '&gt;')
      .replace(/"/g, '&quot;')
      .replace(/'/g, '&#39;');
  }

  function parseMarkdown(md) {
    if (!md) return '';

    let text = md.replace(/\r\n/g, '\n').replace(/\r/g, '\n');

    // 1. Code blocks (```lang ... ```)
    const codeBlocks = [];
    text = text.replace(/```([a-zA-Z0-9_-]*)\n([\s\S]*?)```/g, function (_, lang, code) {
      const id = `__CODE_BLOCK_${codeBlocks.length}__`;
      const escaped = escapeHtml(code.trimEnd());
      const langClass = lang ? ` class="language-${escapeHtml(lang)}"` : '';
      codeBlocks.push(`<pre><code${langClass}>${escaped}</code></pre>`);
      return id;
    });

    // 2. Inline code (`code`)
    const inlineCodes = [];
    text = text.replace(/`([^`\n]+)`/g, function (_, code) {
      const id = `__INLINE_CODE_${inlineCodes.length}__`;
      inlineCodes.push(`<code>${escapeHtml(code)}</code>`);
      return id;
    });

    // 3. Headings (# Heading)
    text = text.replace(/^###### (.*$)/gim, '<h6>$1</h6>');
    text = text.replace(/^##### (.*$)/gim, '<h5>$1</h5>');
    text = text.replace(/^#### (.*$)/gim, '<h4>$1</h4>');
    text = text.replace(/^### (.*$)/gim, '<h3>$1</h3>');
    text = text.replace(/^## (.*$)/gim, '<h2>$1</h2>');
    text = text.replace(/^# (.*$)/gim, '<h1>$1</h1>');

    // 4. Horizontal Rules (---, ***, ___)
    text = text.replace(/^(?:---|\*\*\*|___)\s*$/gim, '<hr />');

    // 5. Blockquotes (> quote)
    text = text.replace(/^\> (.*$)/gim, '<blockquote><p>$1</p></blockquote>');
    // Merge adjacent blockquotes
    text = text.replace(/<\/blockquote>\s*<blockquote>/gim, '\n');

    // 6. Checklists / Task lists (- [ ] or - [x])
    text = text.replace(/^[-*] \[ \] (.*$)/gim, '<li class="task-item"><input type="checkbox" /> <span>$1</span></li>');
    text = text.replace(/^[-*] \[x\] (.*$)/gim, '<li class="task-item task-done"><input type="checkbox" checked /> <span>$1</span></li>');

    // 7. Unordered Lists (- item or * item)
    text = text.replace(/^[-*] (.*$)/gim, '<li>$1</li>');

    // 8. Ordered Lists (1. item)
    text = text.replace(/^\d+\. (.*$)/gim, '<li class="ordered">$1</li>');

    // Wrap continuous <li> into <ul> or <ol>
    text = text.replace(/(<li class="ordered">[\s\S]*?<\/li>)/gim, function (match) {
      return `<ol>${match.replace(/ class="ordered"/g, '')}</ol>`;
    });
    text = text.replace(/(<li(?: class="task-item(?: task-done)?")?>[\s\S]*?<\/li>)/gim, function (match) {
      return `<ul class="list-unstyled">${match}</ul>`;
    });
    // Merge consecutive <ul> and <ol>
    text = text.replace(/<\/ul>\s*<ul class="list-unstyled">/gim, '');
    text = text.replace(/<\/ol>\s*<ol>/gim, '');

    // 9. Tables (| col1 | col2 |)
    text = text.replace(/((?:\|.+?\|\r?\n)+)/g, function (tableBlock) {
      const rows = tableBlock.trim().split('\n').map((r) => r.trim());
      if (rows.length < 2) return tableBlock;

      let html = '<div class="table-wrapper"><table>';
      const isHeaderSep = (row) => /^\|(?:\s*:?-+:?\s*\|)+$/.test(row);

      let headerDone = false;
      rows.forEach((row, idx) => {
        if (idx === 1 && isHeaderSep(row)) {
          headerDone = true;
          return;
        }

        const cols = row.split('|').slice(1, -1);
        const tag = (!headerDone && idx === 0) ? 'th' : 'td';
        const renderedCols = cols.map((c) => `<${tag}>${c.trim()}</${tag}>`).join('');

        if (!headerDone && idx === 0) {
          html += `<thead><tr>${renderedCols}</tr></thead><tbody>`;
        } else {
          html += `<tr>${renderedCols}</tr>`;
        }
      });

      html += '</tbody></table></div>';
      return html;
    });

    // 10. Links and Images
    text = text.replace(/!\[([^\]]*)\]\(([^)]+)\)/g, '<img src="$2" alt="$1" />');
    text = text.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');

    // 11. Text formatting (Bold, Italic, Strikethrough)
    text = text.replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>');
    text = text.replace(/__(.*?)__/g, '<strong>$1</strong>');
    text = text.replace(/~~(.*?)~~/g, '<del>$1</del>');
    text = text.replace(/\*([^*\n]+)\*/g, '<em>$1</em>');
    text = text.replace(/_([^_\n]+)_/g, '<em>$1</em>');

    // 12. Paragraphs (lines separated by blank lines that aren't already HTML blocks)
    const blocks = text.split(/\n{2,}/);
    const parsedBlocks = blocks.map((block) => {
      const trimmed = block.trim();
      if (!trimmed) return '';
      if (/^<(?:h[1-6]|ul|ol|pre|blockquote|div|hr|table)/i.test(trimmed)) {
        return trimmed;
      }
      return `<p>${trimmed.replace(/\n/g, '<br />')}</p>`;
    });

    text = parsedBlocks.join('\n');

    // Restore inline codes
    text = text.replace(/__INLINE_CODE_(\d+)__/g, (_, idx) => inlineCodes[Number(idx)] || '');

    // Restore code blocks
    text = text.replace(/__CODE_BLOCK_(\d+)__/g, (_, idx) => codeBlocks[Number(idx)] || '');

    return text;
  }

  global.marked = {
    parse: parseMarkdown
  };
})(typeof window !== 'undefined' ? window : this);
